const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const choice={'followed':'The recorded recommendation matches the action or successful effect.','different-effect':'A different successful effect was chosen.','proceeded-despite-warning':'The deployment proceeded after the displayed warning.','no-choice-on-failure':'The check failed; no successful effect choice arose.','not-applicable/unknown':'No followed/overruled claim is supported.'};
export function adviceRecordsHTML(records,{archive=false}={}){
 if(!records?.length)return '';
 return `<section class="committed-advice"><details${archive?' open':''}><summary>Advice shown for this action · ${records.length} statement${records.length===1?'':'s'}</summary>${records.map(s=>`<article data-advice-id="${esc(s.id)}"><p><b>${esc(s.speaker)}</b> · ${esc(s.role)}</p><blockquote><p>${esc(s.text)}</p></blockquote><p class="small-note">${esc(s.utterancePhase)} · ${s.shownInAttempt.method==='rendered-before-report'?'Adviser offered this before the result was reported; this does not establish player attention or motivation.':s.shownInAttempt.method==='player-attested-before-check'?'Earlier saved player attestation retained.':'Displayed after reporting; no earlier warning is implied.'}<br>${esc(choice[s.followedStatus])}<br>Reported outcome: ${esc(s.outcomeKind)}. ${s.selectedEffect?'Selected effect: '+esc(s.selectedEffect.kind)+'.':'No successful effect selected.'}</p><details><summary>Source and qualifications</summary><p class="small-note">${esc(s.templateId)} · ${esc(s.id)}<br>Stance: ${esc(s.stance)} · Tone: ${esc(s.confidenceTone)}<br>${esc(s.institutionId)} · ${esc(s.targetIds.join(', '))}</p>${s.qualification.map(q=>`<p>Stated reservation: “${esc(q)}”</p>`).join('')||'<p>No explicit reservation is recorded; this does not constitute a promise of success.</p>'}<p class="small-note">Public evidence: ${esc(s.publicEvidence.map(e=>e.id).join(', '))}. Linked to ${esc(s.incidentId)}. Visibility: participating Company personnel only.</p></details></article>`).join('')}</details></section>`;
}
